/* global d3 */
(() => {
  const stockDataTag = document.getElementById('stock-data');
  const priceSummaryTag = document.getElementById('price-summary');
  if (!stockDataTag) {
    console.error('Missing stock data');
    return;
  }

  const stocks = JSON.parse(stockDataTag.textContent);
  const priceSummary = priceSummaryTag ? JSON.parse(priceSummaryTag.textContent) : {};

  const formatCompact = (value) => {
    if (value === null || value === undefined || Number.isNaN(value)) return '—';
    const abs = Math.abs(value);
    const format = (num) => {
      const fixed = num.toFixed(2).replace(/\.00$/, '');
      return fixed.replace(/\.(\d)0$/, '.$1');
    };
    if (abs >= 1e12) return `${format(value / 1e12)}T`;
    if (abs >= 1e9) return `${format(value / 1e9)}B`;
    if (abs >= 1e6) return `${format(value / 1e6)}M`;
    if (abs >= 1e3) return `${format(value / 1e3)}K`;
    return format(value);
  };

  const formatPrice = (value) => {
    if (value === null || value === undefined || Number.isNaN(value)) return '—';
    return d3.format(',.2f')(value);
  };

  const formatPct = (value) => {
    if (value === null || value === undefined || Number.isNaN(value)) return '—';
    return `${d3.format('+.1%')(value)}`;
  };

  const nodes = stocks.map((d) => {
    const marketCapNum = Number(d.marketCap);
    const hasMarketCap = Number.isFinite(marketCapNum);
    return {
      ticker: d.ticker,
      sector: d.sector || 'Unknown',
      fullName: d.fullName,
      marketCap: hasMarketCap ? marketCapNum : null,
      isEtf: !hasMarketCap,
    };
  });

  const chartContainer = document.getElementById('bubble-chart');
  const legendContainer = document.getElementById('legend');
  const tooltip = d3.select('#tooltip');
  const width = chartContainer.clientWidth;
  const height = chartContainer.clientHeight;

  const svg = d3
    .select(chartContainer)
    .append('svg')
    .attr('width', width)
    .attr('height', height)
    .attr('viewBox', `0 0 ${width} ${height}`)
    .attr('role', 'img')
    .attr('aria-label', 'Bubble chart of stocks grouped by sector');

  const sectors = Array.from(new Set(nodes.map((d) => d.sector)));

  const palette = [
    ...d3.schemeTableau10,
    ...(d3.schemeSet3 || []),
    ...(d3.schemeSet2 || []),
  ];

  const color = d3
    .scaleOrdinal()
    .domain(sectors)
    .range(palette.slice(0, sectors.length));

  const caps = nodes.filter((d) => d.marketCap).map((d) => d.marketCap);
  const radiusScale = d3
    .scaleSqrt()
    .domain([d3.min(caps) || 1, d3.max(caps) || 1])
    .range([12, 48]);

  nodes.forEach((d) => {
    d.radius = d.isEtf ? 14 : radiusScale(d.marketCap);
  });

  const clusterRadius = Math.min(width, height) * 0.22;
  const sectorPositions = {};
  sectors.forEach((sector, i) => {
    const angle = (i / sectors.length) * Math.PI * 2;
    sectorPositions[sector] = {
      x: width / 2 + clusterRadius * Math.cos(angle),
      y: height / 2 + clusterRadius * Math.sin(angle),
    };
  });

  const simulation = d3
    .forceSimulation(nodes)
    .force(
      'x',
      d3.forceX((d) => sectorPositions[d.sector].x).strength(0.08)
    )
    .force(
      'y',
      d3.forceY((d) => sectorPositions[d.sector].y).strength(0.08)
    )
    .force('collide', d3.forceCollide((d) => d.radius + 1))
    .force('center', d3.forceCenter(width / 2, height / 2));

  const nodeGroup = svg.append('g').attr('class', 'nodes');

  const node = nodeGroup
    .selectAll('g')
    .data(nodes)
    .enter()
    .append('g')
    .attr('class', 'node')
    .attr('data-ticker', (d) => d.ticker)
    .call(
      d3
        .drag()
        .on('start', (event, d) => {
          if (!event.active) simulation.alphaTarget(0.2).restart();
          d.fx = d.x;
          d.fy = d.y;
        })
        .on('drag', (event, d) => {
          d.fx = event.x;
          d.fy = event.y;
        })
        .on('end', (event, d) => {
          if (!event.active) simulation.alphaTarget(0);
          d.fx = null;
          d.fy = null;
        })
    );

  node
    .append('circle')
    .attr('r', (d) => d.radius)
    .attr('fill', (d) => color(d.sector))
    .attr('fill-opacity', 0.85)
    .attr('stroke', '#1b1b24')
    .attr('stroke-width', 1.2);

  node
    .append('text')
    .attr('class', 'node-label')
    .attr('text-anchor', 'middle')
    .attr('dominant-baseline', 'central')
    .text((d) => d.ticker)
    .style('font-size', (d) => Math.min(14, Math.max(9, d.radius / 2.2)))
    .style('fill', '#0f1117')
    .style('pointer-events', 'none');

  const showTooltip = (event, d) => {
    if (d.isEtf) return;
    const summary = priceSummary[d.ticker] || {};
    const latestClose = summary.latestClose;
    const change1y = summary.change1y;
    const latestDate = summary.latestDate;
    const extraLines = [];
    if (latestClose !== undefined) {
      const line = `Latest close (${latestDate || 'n/a'}): ${formatPrice(latestClose)}`;
      extraLines.push(line);
    }
    if (change1y !== undefined) {
      extraLines.push(`1Y change: ${formatPct(change1y)}`);
    }

    tooltip
      .style('opacity', 1)
      .html(
        `<div class="tooltip-title">${d.ticker}</div>` +
          `<div class="tooltip-sub">${d.fullName}</div>` +
          `<div class="tooltip-meta">Sector: ${d.sector}</div>` +
          (extraLines.length
            ? `<div class="tooltip-extra">${extraLines.join('<br>')}</div>`
            : '')
      );
  };

  const moveTooltip = (event) => {
    tooltip
      .style('left', `${event.pageX + 14}px`)
      .style('top', `${event.pageY + 14}px`);
  };

  const hideTooltip = () => {
    tooltip.style('opacity', 0);
  };

  node
    .on('mouseenter', showTooltip)
    .on('mousemove', moveTooltip)
    .on('mouseleave', hideTooltip);

  simulation.on('tick', () => {
    node.attr('transform', (d) => `translate(${d.x},${d.y})`);
  });

  const legendItems = d3
    .select(legendContainer)
    .selectAll('div')
    .data(sectors)
    .enter()
    .append('div')
    .attr('class', 'legend-item');

  legendItems
    .append('span')
    .attr('class', 'legend-swatch')
    .style('background-color', (d) => color(d));

  legendItems
    .append('span')
    .attr('class', 'legend-label')
    .text((d) => d);

  const tableBody = d3.select('#stock-table tbody');

  const rows = tableBody
    .selectAll('tr')
    .data(nodes)
    .enter()
    .append('tr')
    .attr('data-ticker', (d) => d.ticker)
    .on('click', (event, d) => {
      setSelected(d.ticker);
    });

  rows.append('td').attr('class', 'cell-ticker').text((d) => d.ticker);
  rows.append('td').attr('class', 'cell-name').text((d) => d.fullName);
  rows.append('td').attr('class', 'cell-sector').text((d) => d.sector);
  rows.append('td').attr('class', 'cell-cap').text((d) => formatCompact(d.marketCap));

  let selectedTicker = null;

  const setSelected = (ticker) => {
    selectedTicker = ticker;
    rows.classed('selected', (d) => d.ticker === selectedTicker);
    node.classed('selected', (d) => d.ticker === selectedTicker);
  };

  node.on('click', (event, d) => {
    event.stopPropagation();
    setSelected(d.ticker);
  });

  svg.on('click', () => {
    setSelected(null);
  });
})();
