const fs = require('fs');
const path = require('path');

const stockPath = '/root/data/stock-descriptions.csv';
const historyDir = '/root/data/indiv-stock';

function parseCsv(text) {
  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    const next = text[i + 1];

    if (char === '"') {
      if (inQuotes && next === '"') {
        field += '"';
        i++;
      } else {
        inQuotes = !inQuotes;
      }
      continue;
    }

    if (char === ',' && !inQuotes) {
      row.push(field);
      field = '';
      continue;
    }

    if ((char === '\n' || char === '\r') && !inQuotes) {
      if (char === '\r' && next === '\n') {
        i++;
      }
      row.push(field);
      field = '';
      if (row.length > 1 || row.some((value) => value.trim() !== '')) {
        rows.push(row);
      }
      row = [];
      continue;
    }

    field += char;
  }

  if (field.length || row.length) {
    row.push(field);
    rows.push(row);
  }

  return rows;
}

const stockCsv = fs.readFileSync(stockPath, 'utf8');
const stockRows = parseCsv(stockCsv);
const headers = stockRows.shift().map((h) => h.trim());

const headerIndex = (name) => headers.indexOf(name);
const idxTicker = headerIndex('ticker');
const idxSector = headerIndex('sector');
const idxName = headerIndex('full name');
const idxCap = headerIndex('marketCap');

const stocks = stockRows
  .map((row) => ({
    ticker: row[idxTicker],
    sector: row[idxSector],
    fullName: row[idxName],
    marketCap: row[idxCap],
  }))
  .filter((d) => d.ticker && d.fullName);

const priceSummary = {};

const historyFiles = new Set(fs.readdirSync(historyDir));

stocks.forEach((stock) => {
  const fileName = `${stock.ticker}.csv`;
  if (!historyFiles.has(fileName)) return;
  const filePath = path.join(historyDir, fileName);
  const text = fs.readFileSync(filePath, 'utf8');
  const lines = text.split(/\r?\n/).filter((line) => line.trim().length > 0);
  if (lines.length < 2) return;
  const headers = lines[0].split(',');
  const dateIndex = headers.indexOf('Date');
  const closeIndex = headers.indexOf('Close');
  if (dateIndex === -1 || closeIndex === -1) return;

  const data = [];
  for (let i = 1; i < lines.length; i++) {
    const parts = lines[i].split(',');
    const date = parts[dateIndex];
    const close = Number(parts[closeIndex]);
    if (!date || Number.isNaN(close)) continue;
    data.push({
      date: new Date(date),
      dateStr: date,
      close,
    });
  }

  if (!data.length) return;

  const latest = data[data.length - 1];
  const targetDate = new Date(latest.date);
  targetDate.setDate(targetDate.getDate() - 365);

  let past = null;
  for (const row of data) {
    if (row.date <= targetDate) {
      past = row;
    } else {
      break;
    }
  }

  if (!past && data.length > 2) {
    past = data[0];
  }

  const change1y = past ? (latest.close - past.close) / past.close : undefined;

  priceSummary[stock.ticker] = {
    latestClose: latest.close,
    latestDate: latest.dateStr,
    change1y,
  };
});

const html = `<!DOCTYPE html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Stock Sector Clusters</title>
