          <h2>Sector Bubble Map</h2>
          <p>ETFs are shown with uniform size and no tooltip details.</p>
          <div id="bubble-chart"></div>
          <div id="legend"></div>
        </section>
        <section class="panel" id="table-panel">
          <h2>Company Details</h2>
          <p>Market caps use compact formatting (e.g., 1.64T).</p>
          <table id="stock-table">
            <thead>
              <tr>
                <th>Ticker symbol</th>
                <th>Full company name</th>
                <th>Sector</th>
                <th>Market cap</th>
              </tr>
            </thead>
            <tbody></tbody>
          </table>
        </section>
      </div>
    </main>
    <div id="tooltip"></div>

    <script id="stock-data" type="application/json">${JSON.stringify(stocks)}</script>
    <script id="price-summary" type="application/json">${JSON.stringify(priceSummary)}</script>
    <script src="js/d3.v6.min.js"></script>
    <script src="js/visualization.js"></script>
  </body>
</html>`;

fs.writeFileSync('/root/output/index.html', html);
NODE"}

